spec.query:
(
  (kube_pod_container_status_last_terminated_reason{reason=~"OOMKilled|Error",namespace="<NAMESPACE>"} == 1)
  * on(pod, namespace) group_left()
  kube_pod_labels{label_resource_name="workflow-queue-workers",namespace="<NAMESPACE>"}
)
and on(namespace, pod, container)
(
  increase(kube_pod_container_status_restarts_total{container!="",container!="POD",namespace="<NAMESPACE>"}[15m]) > 0
)
